  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [
    overlayColorContrast,
    renderedOverlaysUntracked,
    panelScaleCalibration,
    scaleNumbersMatchCalibration,
    lockedMetricFields,
    calibrationSingleSource,
    renderOutputsGitignored,
  ],
  skills: ['vessel-overlay-review', 'paper-intake'],
};

