  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
